const SLOT_DIR: &str = "sd:/ultimate";
const SLOT_FILE: &str = "OnAttackSlots.toml";
const SLOT_FILE_HEADER: &str = "\
# Generated by HDR's on_attack vtable scan hooks.
# Each table records the first observed fighter kind for a skyline on_attack offset.

";

const ON_ATTACK_OFFSET_COUNT: usize = 61;
const FIGHTER_KIND_SLOT_COUNT: usize = 0x78;
const FIGHTER_KIND_WORD_COUNT: usize = (FIGHTER_KIND_SLOT_COUNT + 63) / 64;

struct SlotCache {
    initialized: bool,
    bits: [[u64; FIGHTER_KIND_WORD_COUNT]; ON_ATTACK_OFFSET_COUNT],
}

static SLOT_CACHE: Mutex<SlotCache> = Mutex::new(SlotCache {
    initialized: false,
    bits: [[0; FIGHTER_KIND_WORD_COUNT]; ON_ATTACK_OFFSET_COUNT],
});

macro_rules! define_on_attack_log_hooks {
    ($(($slot:expr, $hook:ident, $offset:expr)),+ $(,)?) => {
        const ON_ATTACK_OFFSETS: [usize; ON_ATTACK_OFFSET_COUNT] = [$($offset),+];

        $(
            #[skyline::hook(offset = $offset)]
            pub unsafe extern "C" fn $hook(
                vtable: u64,
                battleObject: *mut BattleObject,
                collisionLog: CollisionLog,
            ) -> u64 {
                log_on_attack_slot($slot, $offset, vtable, battleObject);
                call_original!(vtable, battleObject, collisionLog)
            }
        )+
    };
}

