#[derive(Clone, Copy)]
struct FighterName {
    kind_name: &'static str,
    fighter: &'static str,
}

fn slot_path() -> PathBuf {
    Path::new(SLOT_DIR).join(SLOT_FILE)
}

fn ensure_slot_file_exists() -> io::Result<()> {
    fs::create_dir_all(SLOT_DIR)?;

    let path = slot_path();
    if !path.exists() {
        fs::write(&path, SLOT_FILE_HEADER)?;
    }

    Ok(())
}

fn with_slot_cache<R>(f: impl FnOnce(&mut SlotCache) -> R) -> R {
    let mut guard = match SLOT_CACHE.lock() {
        Ok(guard) => guard,
        Err(err) => err.into_inner(),
    };
    f(&mut guard)
}

fn offset_slot(offset: usize) -> Option<usize> {
    ON_ATTACK_OFFSETS.iter().position(|known_offset| *known_offset == offset)
}

fn fighter_kind_bit(kind: i32) -> Option<(usize, u64)> {
    if kind < 0 {
        return None;
    }

    let kind = kind as usize;
    if kind >= FIGHTER_KIND_SLOT_COUNT {
        return None;
    }

    Some((kind / 64, 1u64 << (kind % 64)))
}

fn set_slot_bit(bits: &mut [[u64; FIGHTER_KIND_WORD_COUNT]; ON_ATTACK_OFFSET_COUNT], offset: usize, kind: i32) {
    if let (Some(slot), Some((word, mask))) = (offset_slot(offset), fighter_kind_bit(kind)) {
        bits[slot][word] |= mask;
    }
}

fn parse_toml_u64(value: &str) -> Option<u64> {
    let mut value = value.split('#').next().unwrap_or(value).trim();
    if value.starts_with('"') && value.ends_with('"') && value.len() >= 2 {
        value = &value[1..value.len() - 1];
    }

    if let Some(hex) = value.strip_prefix("0x") {
        u64::from_str_radix(hex, 16).ok()
    } else {
        value.parse::<u64>().ok()
    }
}

fn parse_field_u64(line: &str, field: &str) -> Option<u64> {
    let (name, value) = line.split_once('=')?;
    if name.trim() != field {
        return None;
    }

    parse_toml_u64(value)
}

fn load_slot_bits_from_file(bits: &mut [[u64; FIGHTER_KIND_WORD_COUNT]; ON_ATTACK_OFFSET_COUNT]) {
    if let Err(err) = ensure_slot_file_exists() {
        println!("[on_attack_scan] failed to create {}: {}", slot_path().display(), err);
        return;
    }

    let path = slot_path();
    let data = match fs::read_to_string(&path) {
        Ok(data) => data,
        Err(err) => {
            println!("[on_attack_scan] failed reading {}: {}", path.display(), err);
            return;
        }
    };

    let mut offset = None;
    let mut kind = None;

    for line in data.lines().map(str::trim) {
        if line.starts_with("[[") {
            if let (Some(offset), Some(kind)) = (offset, kind) {
                set_slot_bit(bits, offset, kind);
            }
            offset = None;
            kind = None;
            continue;
        }

        if let Some(value) = parse_field_u64(line, "offset") {
            offset = Some(value as usize);
        } else if let Some(value) = parse_field_u64(line, "kind") {
            kind = Some(value as i32);
        }
    }

    if let (Some(offset), Some(kind)) = (offset, kind) {
        set_slot_bit(bits, offset, kind);
    }
}

fn initialize_slot_cache() {
    let mut bits = [[0; FIGHTER_KIND_WORD_COUNT]; ON_ATTACK_OFFSET_COUNT];
    load_slot_bits_from_file(&mut bits);

    with_slot_cache(|cache| {
        for slot in 0..ON_ATTACK_OFFSET_COUNT {
            for word in 0..FIGHTER_KIND_WORD_COUNT {
                cache.bits[slot][word] |= bits[slot][word];
            }
        }
        cache.initialized = true;
    });
}

fn ensure_slot_cache_initialized() {
    let initialized = with_slot_cache(|cache| cache.initialized);
    if !initialized {
        initialize_slot_cache();
    }
}

fn mark_slot_seen_if_new(slot: usize, kind: i32) -> bool {
    let (word, mask) = match fighter_kind_bit(kind) {
        Some(bit) => bit,
        None => return false,
    };

    ensure_slot_cache_initialized();

    with_slot_cache(|cache| {
        if slot >= ON_ATTACK_OFFSET_COUNT {
            return false;
        }

        if cache.bits[slot][word] & mask != 0 {
            return false;
        }

        cache.bits[slot][word] |= mask;
        true
    })
}

fn append_slot_entry(offset: usize, vtable: u64, kind: i32, fighter: FighterName) {
    if let Err(err) = ensure_slot_file_exists() {
        println!("[on_attack_scan] failed to create {}: {}", slot_path().display(), err);
        return;
    }

    let path = slot_path();
    let mut file = match fs::OpenOptions::new().create(true).append(true).open(&path) {
        Ok(file) => file,
        Err(err) => {
            println!("[on_attack_scan] failed opening {}: {}", path.display(), err);
            return;
        }
    };

    let _ = writeln!(file, "[[slots]]");
    let _ = writeln!(file, "offset = \"0x{:x}\"", offset);
    let _ = writeln!(file, "vtable = \"0x{:x}\"", vtable);
    let _ = writeln!(file, "fighter = \"{}\"", fighter.fighter);
    let _ = writeln!(file, "fighter_kind = \"{}\"", fighter.kind_name);
    let _ = writeln!(file, "kind = 0x{:x}", kind);
    let _ = writeln!(file);
}

unsafe fn log_on_attack_slot(slot: usize, offset: usize, vtable: u64, battle_object: *mut BattleObject) {
    if battle_object.is_null() {
        return;
    }

    let boma = &mut (*(&mut *(battle_object)).module_accessor);
    let kind = boma.kind();
    if !mark_slot_seen_if_new(slot, kind) {
        return;
    }

    if let Some(fighter) = fighter_name_from_kind(kind) {
        append_slot_entry(offset, vtable, kind, fighter);
    }
}

